package com.shounak.localmeshai.rag;

import rustanything.RustAnythingError;

/**
 * {@code scoreRelevance} over many {@code content} values kept in Rust, generated by rust-anything: built once,
 * then each {@link #run} maps them all in one call, on all cores. Safe for concurrent use;
 * close it when done (a Cleaner frees it otherwise).
 */
public final class ScoreRelevanceBatch implements AutoCloseable {
    static {
        try {
            Class.forName("rustanything.RagRsNative");
        } catch (ClassNotFoundException e) {
            throw new ExceptionInInitializerError(e);
        }
    }

    private static final java.lang.ref.Cleaner CLEANER = java.lang.ref.Cleaner.create();

    /** The Rust handle; freed once, by {@link #close} or the Cleaner. */
    private static final class State implements Runnable {
        private long handle;

        State(long handle) {
            this.handle = handle;
        }

        @Override
        public synchronized void run() {
            if (handle != 0) {
                nFree(handle);
                handle = 0;
            }
        }

        synchronized long get() {
            if (handle == 0) {
                throw new IllegalStateException("ScoreRelevanceBatch is closed");
            }
            return handle;
        }
    }

    private final State state;
    private final java.lang.ref.Cleaner.Cleanable cleanable;
    private final int count;

    /** Copies the items into Rust. */
    public ScoreRelevanceBatch(String[] contents) {
        state = new State(nNew(contents));
        count = contents.length;
        cleanable = CLEANER.register(this, state);
    }

    /** Copies the items into Rust. */
    public ScoreRelevanceBatch(java.util.List<String> contents) {
        this(contents.toArray(new String[0]));
    }

    private long handle() {
        return state.get();
    }

    /** {@code scoreRelevance}'s result for every item, in order. */
    public double[] run(String query) {
        String[] slot = RustAnythingError.slot();
        double[] out = nRun(handle(), query, slot);
        RustAnythingError.check(slot);
        java.lang.ref.Reference.reachabilityFence(this);
        return out;
    }

    /** Indexes of the items whose result is at least {@code min}, highest result first. */
    public int[] rank(String query, double min) {
        String[] slot = RustAnythingError.slot();
        int[] out = nRank(handle(), query, min, slot);
        RustAnythingError.check(slot);
        java.lang.ref.Reference.reachabilityFence(this);
        return out;
    }

    private static native int[] nRank(long handle, String query, double min, String[] slot);

    /** Frees the items on the Rust side. */
    @Override
    public void close() {
        cleanable.clean();
    }

    private static native long nNew(String[] items);

    private static native void nFree(long handle);

    private static native double[] nRun(long handle, String query, String[] slot);
}
